import {T,createStage,createBook,createTablet,createCard,createGlobe,createCourtyard,clamp,smooth,mix} from './spatial.js';
const mount=document.getElementById('journey3d'),stage=createStage(mount,{dark:true,fov:37});if(!stage){mount.innerHTML='<figure class="spatial-poster journey-poster"><img src="./saudi-landscape.webp" alt="Saudi-inspired architecture and landscape"><figcaption>A world of discovery.</figcaption></figure>'}else{
const {scene,camera,ground}=stage,root=new T.Group();scene.add(root);ground.position.y=-1.4;const book=createBook();root.add(book.root);const tablet=createTablet();root.add(tablet);const content=[createCard('Explore Saudi heritage.','heritage',1.25,.87),createCard('Understand through discovery.','science',1.25,.87)];content.forEach(x=>root.add(x));const world=createGlobe(.48);root.add(world.root);const courtyard=createCourtyard();root.add(courtyard);
let raw=0,phase=0,pointer=0;const steps=[...document.querySelectorAll('.step')];function track(){const marker=innerHeight*.48,positions=steps.map(el=>el.getBoundingClientRect().top);let value=0;for(let i=0;i<3;i++){if(marker>=positions[i])value=i+clamp((marker-positions[i])/(positions[i+1]-positions[i]),0,1)}raw=clamp(value,0,3)}addEventListener('scroll',track,{passive:true});addEventListener('resize',track);track();mount.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const r=mount.getBoundingClientRect();pointer=((e.clientX-r.left)/r.width-.5)*.15});mount.addEventListener('pointerleave',()=>pointer=0);
stage.setDraw((dt,t,reduced)=>{phase=stage.damp(phase,reduced?Math.round(raw):raw,dt,reduced?25:4.5);const digital=smooth(phase,.18,1),interactive=smooth(phase,1.15,1.95),immersive=smooth(phase,2.05,2.95);root.rotation.y=stage.damp(root.rotation.y,pointer-.12+immersive*.15,dt,4);book.root.visible=digital<.985;book.root.position.set(0,-.37-digital*.35,.25-digital*.5);book.root.rotation.set(digital*1.3,0,digital*.09);book.root.scale.set(.83*(1-digital*.18),.83*(1-digital*.4),.83*(1-digital*.1));book.open(1-digital*.8,smooth(phase,0,.34));
tablet.visible=digital>.035;tablet.position.set(0,-.4+digital*.52-immersive*.28,-.12-immersive*.8);tablet.rotation.set(-Math.PI/2*(1-digital)-immersive*.18,-.1+interactive*.15,0);tablet.scale.setScalar(.65+digital*.17-immersive*.24);content.forEach((panel,i)=>{const spread=clamp(interactive*1.24-i*.18,0,1);panel.visible=spread>.015;panel.position.set((i===0?-1:1)*(1.72*spread+.07),.2+spread*(i===0?.88:.46)-immersive*.4,.2+spread*.25);panel.rotation.set(0,(i===0?.23:-.23)*spread,(i===0?-.05:.06)*spread);panel.scale.setScalar(.38+spread*.5-immersive*.18);if(!reduced)panel.position.y+=Math.sin(t*.6+i*2)*.015*spread});world.root.visible=interactive>.02;world.root.position.set(.04,.98+interactive*.5+immersive*.35,.37);world.root.scale.setScalar(.1+interactive*.85-immersive*.25);if(!reduced)world.earth.rotation.y+=dt*.035;
courtyard.visible=immersive>.02;courtyard.position.set(0,-1.03+(1-immersive)*.3,.8);courtyard.scale.set(immersive*1.06,Math.max(.005,immersive*1.06),immersive*1.06);courtyard.rotation.y=.2+immersive*.06;camera.position.set(0,3.35- digital*1.15+immersive*.2,innerWidth<760?9.9:8.9);camera.fov=innerWidth<760?42:37;camera.lookAt(0,.1+interactive*.16,0);camera.updateProjectionMatrix();});
}
